"use client";

import { useEffect, useId, useState } from "react";
import { DownloadIcon, MixerHorizontalIcon, UploadIcon } from "@radix-ui/react-icons";

import { presets } from "@/theme/presets";
import { Button } from "@/components/ui/Button";
import {
  FileUpload,
  FileUploadDropzone,
} from "@/components/ui/FileUpload";
import { Input } from "@/components/ui/Input";
import { Label } from "@/components/ui/Label";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/Popover";
import {
  normalizeHex,
  toColorInputValue,
  useAuraThemeColors,
  type ThemeColors,
} from "@/hooks/use-aura-theme-colors";
import { cn } from "@/utils/class-names";
import { schemeFromSeed, seedFromImage } from "@/utils/scheme-from-seed";

function colorsMatch(
  current: ThemeColors,
  preset: { accent: string; gray: string; background: string }
) {
  return (
    normalizeHex(current.accent) === normalizeHex(preset.accent) &&
    normalizeHex(current.gray) === normalizeHex(preset.gray) &&
    normalizeHex(current.background) === normalizeHex(preset.background)
  );
}

export function ThemeColorSwitcher() {
  const {
    appearance,
    currentColors,
    setTheme,
    setColor,
    applyScheme,
    applyPreset,
    resetDefaults,
    downloadCSS,
  } = useAuraThemeColors();
  const presetsLabelId = useId();
  const seedId = useId();
  const accentId = useId();
  const grayId = useId();
  const backgroundId = useId();

  const [accentInput, setAccentInput] = useState(currentColors.accent);
  const [grayInput, setGrayInput] = useState(currentColors.gray);
  const [backgroundInput, setBackgroundInput] = useState(
    currentColors.background
  );
  const [imageFiles, setImageFiles] = useState<File[]>([]);

  useEffect(() => {
    setAccentInput(currentColors.accent);
    setGrayInput(currentColors.gray);
    setBackgroundInput(currentColors.background);
  }, [currentColors.accent, currentColors.gray, currentColors.background]);

  const handleColorChange = (value: string, field: keyof ThemeColors) => {
    if (field === "accent") setAccentInput(value);
    if (field === "gray") setGrayInput(value);
    if (field === "background") setBackgroundInput(value);
    setColor(field, value);
  };

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          aria-label="Customize colors"
          type="button"
          size="icon"
          variant="pill"
        >
          <MixerHorizontalIcon className="icon" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        className="w-24 max-w-full overflow-x-hidden overflow-y-auto"
        align="end"
      >
        <div className="flex max-h-48 min-w-0 flex-col gap-1 overflow-y-auto p-1">
          <div className="flex items-center justify-between gap-0.5">
            <p className="text-sm font-semibold text-gray-12">Theme Settings</p>
            <div className="flex rounded-sm bg-gray-3 p-0">
              <button
                type="button"
                onClick={() => setTheme("light")}
                className={cn(
                  "cursor-pointer rounded border-none px-0.5 py-0.5 text-xs font-medium",
                  appearance === "light"
                    ? "bg-gray-1 text-gray-12 shadow-sm"
                    : "bg-transparent text-gray-11"
                )}
              >
                Light
              </button>
              <button
                type="button"
                onClick={() => setTheme("dark")}
                className={cn(
                  "cursor-pointer rounded border-none px-0.5 py-0.5 text-xs font-medium",
                  appearance === "dark"
                    ? "bg-gray-1 text-gray-12 shadow-sm"
                    : "bg-transparent text-gray-11"
                )}
              >
                Dark
              </button>
            </div>
          </div>

          <div className="flex min-w-0 flex-col gap-0.5">
            <p id={presetsLabelId} className="text-sm text-gray-12">
              Presets
            </p>
            <div
              className="grid grid-cols-2 gap-0.5"
              role="group"
              aria-labelledby={presetsLabelId}
            >
              {presets.map((preset) => {
                const active = colorsMatch(currentColors, preset);
                return (
                  <button
                    key={preset.id}
                    type="button"
                    aria-pressed={active}
                    aria-label={`${preset.name} color preset`}
                    onClick={() => applyPreset(preset)}
                    className={cn(
                      "flex min-w-0 items-center gap-0.5 rounded border px-0.5 py-0.5 text-start text-sm text-gray-12",
                      "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-8",
                      active
                        ? "border-accent-8 bg-accent-3"
                        : "border-gray-6 bg-gray-1"
                    )}
                  >
                    <span
                      className="flex shrink-0 overflow-hidden rounded-sm border border-gray-6"
                      aria-hidden
                    >
                      <span
                        className="size-1.5"
                        style={{ backgroundColor: preset.accent }}
                      />
                      <span
                        className="size-1.5"
                        style={{ backgroundColor: preset.gray }}
                      />
                      <span
                        className="size-1.5"
                        style={{ backgroundColor: preset.background }}
                      />
                    </span>
                    <span className="truncate">{preset.name}</span>
                  </button>
                );
              })}
            </div>
          </div>

          <div className="flex min-w-0 flex-col gap-0.5">
            <Label htmlFor={seedId}>Seed color</Label>
            <div className="flex min-w-0 items-center gap-0.5">
              <input
                id={seedId}
                type="color"
                value={toColorInputValue(currentColors.accent)}
                aria-label="Seed color"
                className="size-4 shrink-0 cursor-pointer border border-gray-6 bg-transparent p-0"
                onChange={(event) =>
                  applyScheme(schemeFromSeed(event.target.value))
                }
              />
              <span className="text-sm text-gray-12">From image</span>
            </div>
            <FileUpload
              accept="image/*"
              maxFiles={1}
              label="From image"
              className="w-full min-w-0"
              value={imageFiles}
              onValueChange={(next) => {
                setImageFiles(next);
                const file = next[0];
                if (!file) return;
                void seedFromImage(file)
                  .then((seed) => applyScheme(schemeFromSeed(seed)))
                  .catch(() => undefined)
                  .finally(() => setImageFiles([]));
              }}
            >
              <FileUploadDropzone className="w-full min-w-0">
                <UploadIcon className="icon" />
                <span className="min-w-0 text-center text-sm text-gray-11">
                  Drop an image or browse
                </span>
              </FileUploadDropzone>
            </FileUpload>
          </div>

          <ColorField
            id={accentId}
            label="Accent Color"
            value={accentInput}
            color={currentColors.accent}
            placeholder="#4015ca"
            onChange={(value) => handleColorChange(value, "accent")}
          />
          <ColorField
            id={grayId}
            label="Gray Color"
            value={grayInput}
            color={currentColors.gray}
            placeholder="#7254cb"
            onChange={(value) => handleColorChange(value, "gray")}
          />
          <ColorField
            id={backgroundId}
            label="Background Color"
            value={backgroundInput}
            color={currentColors.background}
            placeholder="#100b21"
            onChange={(value) => handleColorChange(value, "background")}
          />

          <div className="grid grid-cols-2 gap-0.5">
            <Button
              type="button"
              variant="pill"
              className="w-full"
              onClick={resetDefaults}
            >
              Reset Defaults
            </Button>
            <Button
              type="button"
              variant="pill"
              className="w-full"
              onClick={downloadCSS}
            >
              <DownloadIcon className="icon" />
              Download CSS
            </Button>
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
}

function ColorField({
  id,
  label,
  value,
  color,
  placeholder,
  onChange,
}: {
  id: string;
  label: string;
  value: string;
  color: string;
  placeholder: string;
  onChange: (value: string) => void;
}) {
  return (
    <div className="flex min-w-0 flex-col gap-0.5">
      <Label htmlFor={id}>{label}</Label>
      <div className="flex min-w-0 items-center gap-0.5">
        <div className="min-w-0 flex-1">
          <Input
            id={id}
            type="text"
            value={value}
            placeholder={placeholder}
            spellCheck={false}
            autoCapitalize="off"
            onChange={(event) => onChange(event.target.value)}
            className="w-full"
          />
        </div>
        <input
          type="color"
          aria-label={label}
          value={toColorInputValue(color, placeholder)}
          onChange={(event) => onChange(event.target.value)}
          className="size-4 shrink-0 cursor-pointer border border-gray-6 bg-transparent p-0"
        />
      </div>
    </div>
  );
}

"use client";

import { useCallback, useLayoutEffect, useState, useSyncExternalStore } from "react";
import { useTheme } from "next-themes";

import { generateRadixColors } from "@/utils/custom-color-functions";

const AURA_THEME_COLORS_KEY = "aura-theme-colors";

export type ThemeColors = {
  accent: string;
  gray: string;
  background: string;
};

export type ThemeColorsByMode = {
  light: ThemeColors;
  dark: ThemeColors;
};

export const DEFAULT_THEME_COLORS: ThemeColorsByMode = {
  light: { accent: "#4015ca", gray: "#7254cb", background: "#ffffff" },
  dark: { accent: "#4015ca", gray: "#7254cb", background: "#100b21" },
};

const STORAGE_KEY = AURA_THEME_COLORS_KEY;
const CHANGE_EVENT = "aura-theme-colors-change";

const LIGHT_BACKGROUND_LUMINANCE = 0.4;

let pinnedAppearance: "light" | "dark" | null = null;

type Listener = () => void;

let memoryStore: ThemeColorsByMode = DEFAULT_THEME_COLORS;
let didHydrateFromStorage = false;
const listeners = new Set<Listener>();

function emitChange() {
  listeners.forEach((listener) => listener());
  if (typeof window !== "undefined") {
    window.dispatchEvent(new Event(CHANGE_EVENT));
  }
}

function sameThemeColors(a: ThemeColors, b: ThemeColors) {
  return (
    a.accent === b.accent && a.gray === b.gray && a.background === b.background
  );
}

function sameThemeColorsByMode(a: ThemeColorsByMode, b: ThemeColorsByMode) {
  return (
    sameThemeColors(a.light, b.light) && sameThemeColors(a.dark, b.dark)
  );
}

function isValidThemeColors(value: unknown): value is ThemeColors {
  if (!value || typeof value !== "object") return false;
  const colors = value as ThemeColors;
  return (
    typeof colors.accent === "string" &&
    typeof colors.gray === "string" &&
    typeof colors.background === "string" &&
    isValidHex(colors.accent) &&
    isValidHex(colors.gray) &&
    isValidHex(colors.background)
  );
}

function isValidThemeColorsByMode(value: unknown): value is ThemeColorsByMode {
  if (!value || typeof value !== "object") return false;
  const parsed = value as ThemeColorsByMode;
  return isValidThemeColors(parsed.light) && isValidThemeColors(parsed.dark);
}

function clearCorruptStorage() {
  if (typeof window === "undefined") return;
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch {
  }
}

function toNormalizedThemeColors(colors: ThemeColors): ThemeColors {
  return {
    accent: normalizeHex(colors.accent),
    gray: normalizeHex(colors.gray),
    background: normalizeHex(colors.background),
  };
}

function readFromStorage(): ThemeColorsByMode {
  if (typeof window === "undefined") return memoryStore;
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (!saved) return memoryStore;
    const parsed = JSON.parse(saved) as unknown;
    if (isValidThemeColorsByMode(parsed)) {
      const next: ThemeColorsByMode = {
        light: toNormalizedThemeColors(parsed.light),
        dark: toNormalizedThemeColors(parsed.dark),
      };
      if (!sameThemeColorsByMode(memoryStore, next)) {
        memoryStore = next;
      }
      return memoryStore;
    }
    clearCorruptStorage();
  } catch {
    clearCorruptStorage();
  }
  if (!sameThemeColorsByMode(memoryStore, DEFAULT_THEME_COLORS)) {
    memoryStore = DEFAULT_THEME_COLORS;
  }
  return memoryStore;
}

function writeToStorage(next: ThemeColorsByMode) {
  const safeNext = isValidThemeColorsByMode(next)
    ? {
        light: toNormalizedThemeColors(next.light),
        dark: toNormalizedThemeColors(next.dark),
      }
    : DEFAULT_THEME_COLORS;
  if (sameThemeColorsByMode(memoryStore, safeNext)) return;
  memoryStore = safeNext;
  if (typeof window !== "undefined") {
    try {
      localStorage.setItem(STORAGE_KEY, serializeTheme(safeNext));
    } catch {
    }
  }
  emitChange();
}

export function pinAppearance(mode: "light" | "dark") {
  pinnedAppearance = mode;
}

export function consumePaintAppearance(
  resolved: string | undefined
): "light" | "dark" | null {
  if (resolved === "light" || resolved === "dark") {
    if (pinnedAppearance && pinnedAppearance !== resolved) return pinnedAppearance;
    pinnedAppearance = null;
    return resolved;
  }
  return pinnedAppearance;
}

function subscribe(listener: Listener) {
  listeners.add(listener);
  const onStorage = (event: StorageEvent) => {
    if (event.key !== STORAGE_KEY) return;
    readFromStorage();
    listener();
  };
  const onCustom = () => listener();
  if (typeof window !== "undefined") {
    window.addEventListener("storage", onStorage);
    window.addEventListener(CHANGE_EVENT, onCustom);
  }
  return () => {
    listeners.delete(listener);
    if (typeof window !== "undefined") {
      window.removeEventListener("storage", onStorage);
      window.removeEventListener(CHANGE_EVENT, onCustom);
    }
  };
}

export function getSnapshot() {
  if (typeof window !== "undefined" && !didHydrateFromStorage) {
    didHydrateFromStorage = true;
    readFromStorage();
  }
  return memoryStore;
}

function getServerSnapshot() {
  return DEFAULT_THEME_COLORS;
}

export function isValidHex(hex: string) {
  return (
    typeof hex === "string" &&
    /^#?([0-9A-Fa-f]{3}|[0-9A-Fa-f]{6})$/.test(hex.trim())
  );
}

export function normalizeHex(value: string) {
  const raw = value.trim();
  const withHash = raw.startsWith("#") ? raw : `#${raw}`;
  const body = withHash.slice(1);
  if (body.length === 3) {
    return `#${body
      .split("")
      .map((char) => `${char}${char}`)
      .join("")}`.toLowerCase();
  }
  return `#${body}`.toLowerCase();
}

export function toColorInputValue(value: string, fallback = "#4015ca") {
  if (!isValidHex(value)) return normalizeHex(fallback);
  return normalizeHex(value);
}

export function safeGenerateRadixColors(input: {
  appearance: "light" | "dark";
  accent: string;
  gray: string;
  background: string;
}) {
  try {
    if (
      !isValidHex(input.accent) ||
      !isValidHex(input.gray) ||
      !isValidHex(input.background)
    ) {
      return null;
    }
    return generateRadixColors({
      appearance: input.appearance,
      accent: normalizeHex(input.accent),
      gray: normalizeHex(input.gray),
      background: normalizeHex(input.background),
    });
  } catch {
    return null;
  }
}

export function backgroundLuminance(hex: string) {
  const normalized = normalizeHex(hex).slice(1);
  const channel = (start: number) => {
    const value = parseInt(normalized.slice(start, start + 2), 16) / 255;
    return value <= 0.04045
      ? value / 12.92
      : ((value + 0.055) / 1.055) ** 2.4;
  };
  return (
    0.2126 * channel(0) + 0.7152 * channel(2) + 0.0722 * channel(4)
  );
}

export function appearanceForBackground(hex: string): "light" | "dark" {
  return backgroundLuminance(hex) >= LIGHT_BACKGROUND_LUMINANCE
    ? "light"
    : "dark";
}

export function themeColorVariables(
  appearance: "light" | "dark",
  colors: ThemeColors
) {
  const generated = safeGenerateRadixColors({
    appearance,
    accent: colors.accent,
    gray: colors.gray,
    background: colors.background,
  });
  if (!generated) return null;

  const vars: Record<string, string> = {};
  const set = (name: string, value: string) => {
    vars[name] = value;
  };
  const setScale = (name: string, scale: string[], alphaScale: string[]) => {
    scale.forEach((value, index) => {
      set(`--${name}-${index + 1}`, value);
    });
    alphaScale.forEach((value, index) => {
      set(`--${name}-a${index + 1}`, value);
    });
  };

  setScale("accent", generated.accentScale, generated.accentScaleAlpha);
  setScale("gray", generated.grayScale, generated.grayScaleAlpha);

  generated.accentScaleWideGamut.forEach((value, index) => {
    set(`--accent-${index + 1}-wide`, value);
  });
  generated.accentScaleAlphaWideGamut.forEach((value, index) => {
    set(`--accent-a${index + 1}-wide`, value);
  });
  generated.grayScaleWideGamut.forEach((value, index) => {
    set(`--gray-${index + 1}-wide`, value);
  });
  generated.grayScaleAlphaWideGamut.forEach((value, index) => {
    set(`--gray-a${index + 1}-wide`, value);
  });

  set("--accent-contrast", generated.accentContrast);
  set("--accent-surface", generated.accentSurface);
  set("--accent-surface-wide", generated.accentSurfaceWideGamut);
  set("--gray-surface", generated.graySurface);
  set("--gray-surface-wide", generated.graySurfaceWideGamut);
  set("--accent-indicator", generated.accentScale[8]);
  set("--accent-track", generated.accentScale[8]);
  set("--gray-indicator", generated.grayScale[8]);
  set("--gray-track", generated.grayScale[8]);
  set("--primary", "var(--accent-9)");
  set("--primary-foreground", "var(--accent-contrast)");
  set("--secundary", "var(--accent-8)");
  set("--secundary-foreground", "var(--accent-contrast)");

  return vars;
}

function serializeTheme(colors: ThemeColorsByMode) {
  return JSON.stringify({
    light: colors.light,
    dark: colors.dark,
    css: {
      light: themeColorVariables("light", colors.light) ?? {},
      dark: themeColorVariables("dark", colors.dark) ?? {},
    },
  });
}

export function injectThemeColors(
  appearance: "light" | "dark",
  colors: ThemeColors
) {
  if (typeof document === "undefined") return null;
  const vars = themeColorVariables(appearance, colors);
  if (!vars) return null;
  const rootElement = document.documentElement;
  for (const [name, value] of Object.entries(vars)) {
    rootElement.style.setProperty(name, value);
  }
  return vars;
}

export function generateGlobalsCssContent(
  themeColors: ThemeColorsByMode
): string {
  const lightColors =
    safeGenerateRadixColors({
      appearance: "light",
      accent: themeColors.light.accent,
      gray: themeColors.light.gray,
      background: themeColors.light.background,
    }) ??
    generateRadixColors({
      appearance: "light",
      accent: DEFAULT_THEME_COLORS.light.accent,
      gray: DEFAULT_THEME_COLORS.light.gray,
      background: DEFAULT_THEME_COLORS.light.background,
    });

  const darkColors =
    safeGenerateRadixColors({
      appearance: "dark",
      accent: themeColors.dark.accent,
      gray: themeColors.dark.gray,
      background: themeColors.dark.background,
    }) ??
    generateRadixColors({
      appearance: "dark",
      accent: DEFAULT_THEME_COLORS.dark.accent,
      gray: DEFAULT_THEME_COLORS.dark.gray,
      background: DEFAULT_THEME_COLORS.dark.background,
    });

  const generateScaleVars = (
    name: string,
    scale: string[],
    alphaScale: string[]
  ) => {
    let css = "";
    scale.forEach((val, i) => {
      css += `  --${name}-${i + 1}: ${val};\n`;
    });
    css += "\n";
    alphaScale.forEach((val, i) => {
      css += `  --${name}-a${i + 1}: ${val};\n`;
    });
    return css;
  };

  const generateExtraVars = (
    name: string,
    colors: ReturnType<typeof generateRadixColors>
  ) => {
    const contrast = name === "accent" ? colors.accentContrast : "#ffffff";
    const surface =
      name === "accent" ? colors.accentSurface : colors.graySurface;
    const indicator =
      name === "accent" ? colors.accentScale[8] : colors.grayScale[8];
    const track =
      name === "accent" ? colors.accentScale[8] : colors.grayScale[8];

    return `  --${name}-contrast: ${contrast};
  --${name}-surface: ${surface};
  --${name}-indicator: ${indicator};
  --${name}-track: ${track};\n`;
  };

  return `@import "tailwindcss";

@theme inline {
  --spacing: 13px;
  --font-sans: var(--font-gabarito, "Gabarito"), sans-serif;
  --info: #e8ebfe;
  --info-contrast: #0927ec;
  --success: #e8fef7;
  --success-contrast: #045d3c;
  --danger: #feefe8;
  --danger-contrast: #8e3106;
  --warning: #fefbe8;
  --warning-contrast: #5d5104;
  --radius-sm: calc(var(--spacing) * 0.5);
  --radius-md: calc(var(--spacing) * 1);
  --radius-lg: calc(var(--spacing) * 1.5);
  --radius-xl: calc(var(--spacing) * 2);
  --aura-loader: var(--aura-loader);
  --color-warning-contrast: var(--warning-contrast);
  --color-warning: var(--warning);
  --color-danger-contrast: var(--danger-contrast);
  --color-danger: var(--danger);
  --color-success-contrast: var(--success-contrast);
  --color-success: var(--success);
  --color-info-contrast: var(--info-contrast);
  --color-info: var(--info);
  --secundary-foreground: var(--secundary-foreground);
  --secundary: var(--secundary);
  --primary-foreground: var(--primary-foreground);
  --primary: var(--primary);
  --color-gray-track: var(--gray-track);
  --color-gray-indicator: var(--gray-indicator);
  --color-gray-surface: var(--gray-surface);
  --color-gray-contrast: var(--gray-contrast);
  --color-gray-a12: var(--gray-a12);
  --color-gray-a11: var(--gray-a11);
  --color-gray-a10: var(--gray-a10);
  --color-gray-a9: var(--gray-a9);
  --color-gray-a8: var(--gray-a8);
  --color-gray-a7: var(--gray-a7);
  --color-gray-a6: var(--gray-a6);
  --color-gray-a5: var(--gray-a5);
  --color-gray-a4: var(--gray-a4);
  --color-gray-a3: var(--gray-a3);
  --color-gray-a2: var(--gray-a2);
  --color-gray-a1: var(--gray-a1);
  --color-gray-12: var(--gray-12);
  --color-gray-11: var(--gray-11);
  --color-gray-10: var(--gray-10);
  --color-gray-9: var(--gray-9);
  --color-gray-8: var(--gray-8);
  --color-gray-7: var(--gray-7);
  --color-gray-6: var(--gray-6);
  --color-gray-5: var(--gray-5);
  --color-gray-4: var(--gray-4);
  --color-gray-3: var(--gray-3);
  --color-gray-2: var(--gray-2);
  --color-gray-1: var(--gray-1);
  --color-accent-track: var(--accent-track);
  --color-accent-indicator: var(--accent-indicator);
  --color-accent-surface: var(--accent-surface);
  --color-accent-contrast: var(--accent-contrast);
  --color-accent-a12: var(--accent-a12);
  --color-accent-a11: var(--accent-a11);
  --color-accent-a10: var(--accent-a10);
  --color-accent-a9: var(--accent-a9);
  --color-accent-a8: var(--accent-a8);
